        # PnL ve Temel Hesaplamalar
        pnl = (price - pos.entry) * pos.qty if pos.side == "LONG" else (pos.entry - price) * pos.qty

        # Ters Rejim Takibi
        if signal.get('REJIM_DONUS'):
            pos.ters_rejim_sayaci += 1
        else:
            pos.ters_rejim_sayaci = 0

        # Kapatma Koşulları
        if pos.ters_rejim_sayaci >= 20:
            return "REJIM_SAYAC_STOP"

        # BE Kilidi ve Trailing Mantığı (Korunan Kısım)
        if pos.side == "LONG":
            if pnl > pos.be_threshold:
                pos.be_locked = True
            if pos.be_locked and price > pos.entry:
                pos.stop = max(pos.stop, price - pos.trailing_dist)
            if price <= pos.stop:
                return "STOP_LOSS"
        else:
            if pnl > pos.be_threshold:
                pos.be_locked = True
            if pos.be_locked and price < pos.entry:
                pos.stop = min(pos.stop, price + pos.trailing_dist)
            if price >= pos.stop:
                return "STOP_LOSS"

        # Zombi ve Genel PnL Kontrolü
        if pos.is_zombie and pnl < 0:
            return "ZOMBIE_EXIT"

        return None"
  }
